<?php
/** Catalog with category sidebar and server-side filtering. */
if ( ! defined( 'ABSPATH' ) ) { exit; }
$categories = raghushree_catalog_definitions();
$category = isset( $_GET['polymer_cat'] ) && is_scalar( $_GET['polymer_cat'] ) ? sanitize_title( wp_unslash( $_GET['polymer_cat'] ) ) : '';
if ( is_tax( 'polymer_category' ) && '' === $category ) { $term = get_queried_object(); if ( $term instanceof WP_Term ) { $category = $term->slug; } }
$search = isset( $_GET['product_q'] ) && is_scalar( $_GET['product_q'] ) ? sanitize_text_field( wp_unslash( $_GET['product_q'] ) ) : '';
$paged = isset( $_GET['catalog_page'] ) && is_scalar( $_GET['catalog_page'] ) ? max( 1, absint( $_GET['catalog_page'] ) ) : 1;
$allowed = array_keys( $categories ); $selected = isset( $categories[$category] ) ? array( $category ) : $allowed;
$catalog = new WP_Query( array( 'post_type' => 'products', 'post_status' => 'publish', 'posts_per_page' => 24, 'post__not_in' => get_option( 'raghushree_catalog_v2' ) ? (array) get_option( 'raghushree_legacy_catalog_ids', array() ) : array(), 'paged' => $paged, 's' => $search, 'orderby' => 'title', 'order' => 'ASC', 'tax_query' => array( array( 'taxonomy' => 'polymer_category', 'field' => 'slug', 'terms' => $selected ) ) ) );
$grouped = array(); foreach ( $catalog->posts as $post ) { $terms = get_the_terms( $post->ID, 'polymer_category' ); if ( ! is_array( $terms ) ) { continue; } foreach ( $terms as $term ) { if ( in_array( $term->slug, $selected, true ) ) { $grouped[$term->slug][] = $post->ID; break; } } }
?>
<section class="catalog-hero"><div class="container"><span class="eyebrow"><?php esc_html_e( 'Raghushree product collection', 'raghushree' ); ?></span><h1><?php esc_html_e( 'Materials & pipes, thoughtfully sourced.', 'raghushree' ); ?></h1><p><?php esc_html_e( 'Explore our polymer materials, hoses and piping products by category.', 'raghushree' ); ?></p></div></section>
<section class="section surface--pearl"><div class="container catalog-layout">
	<aside class="catalog-sidebar" aria-label="<?php esc_attr_e( 'Product categories', 'raghushree' ); ?>"><h2><?php esc_html_e( 'Categories', 'raghushree' ); ?></h2><a class="catalog-sidebar__link <?php echo '' === $category ? 'is-active' : ''; ?>" href="<?php echo esc_url( raghushree_get_products_url() ); ?>"><?php esc_html_e( 'All products', 'raghushree' ); ?></a>
		<?php foreach ( array( 'polymer' => 'Polymer materials', 'pipe' => 'Pipes & hoses' ) as $type => $label ) : ?><h3><?php echo esc_html( $label ); ?></h3><?php foreach ( $categories as $slug => $cat ) : if ( $cat['type'] !== $type ) { continue; } ?><a class="catalog-sidebar__link <?php echo $category === $slug ? 'is-active' : ''; ?>" href="<?php echo esc_url( raghushree_get_products_url( array( 'polymer_cat' => $slug ) ) ); ?>"><?php echo esc_html( $cat['title'] ); ?></a><?php endforeach; endforeach; ?>
	</aside>
	<div class="catalog-main"><form class="catalog-search" method="get" action="<?php echo esc_url( raghushree_get_products_url() ); ?>"><label class="screen-reader-text" for="catalog-search"><?php esc_html_e( 'Search products', 'raghushree' ); ?></label><input id="catalog-search" type="search" name="product_q" value="<?php echo esc_attr( $search ); ?>" placeholder="<?php esc_attr_e( 'Search products', 'raghushree' ); ?>"><?php if ( isset( $categories[$category] ) ) : ?><input type="hidden" name="polymer_cat" value="<?php echo esc_attr( $category ); ?>"><?php endif; ?><button class="btn btn--primary" type="submit"><?php esc_html_e( 'Search', 'raghushree' ); ?></button></form>
		<p class="catalog-count"><?php echo esc_html( sprintf( _n( '%d product found', '%d products found', $catalog->found_posts, 'raghushree' ), $catalog->found_posts ) ); ?></p>
		<?php if ( ! $catalog->have_posts() ) : ?><div class="products-empty"><h2><?php esc_html_e( 'No products found', 'raghushree' ); ?></h2><p><?php esc_html_e( 'Try another search or category, or contact us for assistance.', 'raghushree' ); ?></p></div><?php endif; ?>
		<?php foreach ( $categories as $slug => $cat ) : if ( empty( $grouped[$slug] ) ) { continue; } ?><section class="catalog-group"><div class="catalog-group__heading"><div><span class="eyebrow"><?php echo esc_html( 'pipe' === $cat['type'] ? 'Pipes & hoses' : 'Polymer materials' ); ?></span><h2><?php echo esc_html( $cat['title'] ); ?></h2></div></div><div class="product-grid"><?php foreach ( $grouped[$slug] as $id ) { get_template_part( 'template-parts/components/product-card', null, array( 'product_id' => $id ) ); } ?></div></section><?php endforeach; ?>
		<?php if ( $catalog->max_num_pages > 1 ) : ?><nav aria-label="<?php esc_attr_e( 'Catalog pages', 'raghushree' ); ?>" class="catalog-pagination"><?php for ( $i = 1; $i <= $catalog->max_num_pages; $i++ ) : ?><a <?php echo $i === $paged ? 'aria-current="page"' : ''; ?> href="<?php echo esc_url( add_query_arg( array( 'polymer_cat' => $category, 'product_q' => $search, 'catalog_page' => $i ), raghushree_get_products_url() ) ); ?>"><?php echo esc_html( $i ); ?></a><?php endfor; ?></nav><?php endif; ?>
	</div>
</div></section>
